referenceSolutions.javascript:
export function designHitCounter(operations                     )                  {
const hits         =[];let first=0;return operations.map(op=>{const t=Number(op[1]);while(first<hits.length&&hits[first]<=t-300)first++;if(op[0]==='hit'){hits.push(t);return null;}return hits.length-first;});
}

